SET ANSI_NULLS ON;SET QUOTED_IDENTIFIER ON;SET ANSI_PADDING ON;
CREATE TABLE dbo.CRMAprendizajePaquete(InstitutionId uniqueidentifier NOT NULL,PackId uniqueidentifier NOT NULL,Task varchar(32) NOT NULL,Scope varchar(8) NOT NULL,Revision int NOT NULL,TrainEnabled bit NOT NULL,Document nvarchar(max) NOT NULL,ActorId uniqueidentifier NOT NULL,CreatedAt datetime2(7) NOT NULL CONSTRAINT DF_P10PackFecha DEFAULT SYSUTCDATETIME(),CONSTRAINT PK_P10Pack PRIMARY KEY(InstitutionId,PackId),CONSTRAINT FK_P10PackActor FOREIGN KEY(InstitutionId,ActorId) REFERENCES dbo.CRMAccesoUsuario(InstitutionId,UserId),CONSTRAINT CK_P10Pack CHECK(ISJSON(Document)=1 AND (Task IN('lead_scoring','churn_prediction','smart_remarketing','operational_anomaly') AND Scope IN('demo','native') AND Revision>0)));
CREATE TABLE dbo.CRMAprendizajePaqueteVersion(InstitutionId uniqueidentifier NOT NULL,VersionId uniqueidentifier NOT NULL,PackId uniqueidentifier NOT NULL,VersionNo int NOT NULL,DocumentHash char(64) NOT NULL,Document nvarchar(max) NOT NULL,ActorId uniqueidentifier NOT NULL,CreatedAt datetime2(7) NOT NULL CONSTRAINT DF_P10PackVersionFecha DEFAULT SYSUTCDATETIME(),CONSTRAINT PK_P10PackVersion PRIMARY KEY(InstitutionId,VersionId),CONSTRAINT FK_P10PackVersionActor FOREIGN KEY(InstitutionId,ActorId) REFERENCES dbo.CRMAccesoUsuario(InstitutionId,UserId),CONSTRAINT CK_P10PackVersion CHECK(ISJSON(Document)=1 AND (VersionNo>0)));
ALTER TABLE dbo.CRMAprendizajePaqueteVersion ADD CONSTRAINT FK_P10PackVersionPack FOREIGN KEY(InstitutionId,PackId) REFERENCES dbo.CRMAprendizajePaquete(InstitutionId,PackId);
ALTER TABLE dbo.CRMAprendizajePaqueteVersion ADD CONSTRAINT UQ_P10PackVersionPack UNIQUE(InstitutionId,PackId,VersionId);
CREATE TABLE dbo.CRMAprendizajeAutorizacion(InstitutionId uniqueidentifier NOT NULL,GrantId uniqueidentifier NOT NULL,PackId uniqueidentifier NOT NULL,GroupKey char(64) NOT NULL,SubjectId uniqueidentifier NULL,Purpose varchar(60) NOT NULL,State varchar(8) NOT NULL,Revision int NOT NULL,Document nvarchar(max) NOT NULL,ActorId uniqueidentifier NOT NULL,CreatedAt datetime2(7) NOT NULL CONSTRAINT DF_P10GrantFecha DEFAULT SYSUTCDATETIME(),CONSTRAINT PK_P10Grant PRIMARY KEY(InstitutionId,GrantId),CONSTRAINT FK_P10GrantActor FOREIGN KEY(InstitutionId,ActorId) REFERENCES dbo.CRMAccesoUsuario(InstitutionId,UserId),CONSTRAINT CK_P10Grant CHECK(ISJSON(Document)=1 AND (State IN('active','revoked') AND Revision>0)));
ALTER TABLE dbo.CRMAprendizajeAutorizacion ADD CONSTRAINT FK_P10GrantPack FOREIGN KEY(InstitutionId,PackId) REFERENCES dbo.CRMAprendizajePaquete(InstitutionId,PackId);
ALTER TABLE dbo.CRMAprendizajeAutorizacion ADD CONSTRAINT UQ_P10GrantPack UNIQUE(InstitutionId,PackId,GrantId);
CREATE TABLE dbo.CRMAprendizajeMuestra(InstitutionId uniqueidentifier NOT NULL,SampleId uniqueidentifier NOT NULL,PackId uniqueidentifier NOT NULL,GrantId uniqueidentifier NOT NULL,VersionId uniqueidentifier NOT NULL,GroupKey char(64) NOT NULL,SourceKind varchar(16) NOT NULL,SourceId uniqueidentifier NULL,ProgramKey nvarchar(80) NOT NULL,StageKey nvarchar(80) NOT NULL,FeatureAt datetime2(7) NOT NULL,OutcomeAt datetime2(7) NOT NULL,Label bit NOT NULL,Supersedes uniqueidentifier NULL,DocumentHash char(64) NOT NULL,Document nvarchar(max) NOT NULL,ActorId uniqueidentifier NOT NULL,CreatedAt datetime2(7) NOT NULL CONSTRAINT DF_P10SampleFecha DEFAULT SYSUTCDATETIME(),CONSTRAINT PK_P10Sample PRIMARY KEY(InstitutionId,SampleId),CONSTRAINT FK_P10SampleActor FOREIGN KEY(InstitutionId,ActorId) REFERENCES dbo.CRMAccesoUsuario(InstitutionId,UserId),CONSTRAINT CK_P10Sample CHECK(ISJSON(Document)=1 AND (FeatureAt<OutcomeAt AND SourceKind IN('conversation','campaign','admissions','demo'))));
ALTER TABLE dbo.CRMAprendizajeMuestra ADD CONSTRAINT FK_P10SamplePack FOREIGN KEY(InstitutionId,PackId) REFERENCES dbo.CRMAprendizajePaquete(InstitutionId,PackId);
ALTER TABLE dbo.CRMAprendizajeMuestra ADD CONSTRAINT UQ_P10SamplePack UNIQUE(InstitutionId,PackId,SampleId);
CREATE TABLE dbo.CRMAprendizajeConjunto(InstitutionId uniqueidentifier NOT NULL,DatasetId uniqueidentifier NOT NULL,PackId uniqueidentifier NOT NULL,VersionId uniqueidentifier NOT NULL,DocumentHash char(64) NOT NULL,Document nvarchar(max) NOT NULL,ActorId uniqueidentifier NOT NULL,CreatedAt datetime2(7) NOT NULL CONSTRAINT DF_P10DatasetFecha DEFAULT SYSUTCDATETIME(),CONSTRAINT PK_P10Dataset PRIMARY KEY(InstitutionId,DatasetId),CONSTRAINT FK_P10DatasetActor FOREIGN KEY(InstitutionId,ActorId) REFERENCES dbo.CRMAccesoUsuario(InstitutionId,UserId),CONSTRAINT CK_P10Dataset CHECK(ISJSON(Document)=1 AND (1=1)));
ALTER TABLE dbo.CRMAprendizajeConjunto ADD CONSTRAINT FK_P10DatasetPack FOREIGN KEY(InstitutionId,PackId) REFERENCES dbo.CRMAprendizajePaquete(InstitutionId,PackId);
ALTER TABLE dbo.CRMAprendizajeConjunto ADD CONSTRAINT UQ_P10DatasetPack UNIQUE(InstitutionId,PackId,DatasetId);
CREATE TABLE dbo.CRMAprendizajeArtefacto(InstitutionId uniqueidentifier NOT NULL,ArtifactId uniqueidentifier NOT NULL,PackId uniqueidentifier NOT NULL,DatasetId uniqueidentifier NOT NULL,DocumentHash char(64) NOT NULL,Document nvarchar(max) NOT NULL,ActorId uniqueidentifier NOT NULL,CreatedAt datetime2(7) NOT NULL CONSTRAINT DF_P10ArtifactFecha DEFAULT SYSUTCDATETIME(),CONSTRAINT PK_P10Artifact PRIMARY KEY(InstitutionId,ArtifactId),CONSTRAINT FK_P10ArtifactActor FOREIGN KEY(InstitutionId,ActorId) REFERENCES dbo.CRMAccesoUsuario(InstitutionId,UserId),CONSTRAINT CK_P10Artifact CHECK(ISJSON(Document)=1 AND (1=1)));
ALTER TABLE dbo.CRMAprendizajeArtefacto ADD CONSTRAINT FK_P10ArtifactPack FOREIGN KEY(InstitutionId,PackId) REFERENCES dbo.CRMAprendizajePaquete(InstitutionId,PackId);
ALTER TABLE dbo.CRMAprendizajeArtefacto ADD CONSTRAINT UQ_P10ArtifactPack UNIQUE(InstitutionId,PackId,ArtifactId);
CREATE TABLE dbo.CRMAprendizajeDespliegue(InstitutionId uniqueidentifier NOT NULL,DeploymentId uniqueidentifier NOT NULL,PackId uniqueidentifier NOT NULL,ActiveId uniqueidentifier NULL,ShadowId uniqueidentifier NULL,State varchar(8) NOT NULL,Revision int NOT NULL,Document nvarchar(max) NOT NULL,ActorId uniqueidentifier NOT NULL,CreatedAt datetime2(7) NOT NULL CONSTRAINT DF_P10DeploymentFecha DEFAULT SYSUTCDATETIME(),CONSTRAINT PK_P10Deployment PRIMARY KEY(InstitutionId,DeploymentId),CONSTRAINT FK_P10DeploymentActor FOREIGN KEY(InstitutionId,ActorId) REFERENCES dbo.CRMAccesoUsuario(InstitutionId,UserId),CONSTRAINT CK_P10Deployment CHECK(ISJSON(Document)=1 AND (State IN('enabled','paused') AND Revision>0)));
ALTER TABLE dbo.CRMAprendizajeDespliegue ADD CONSTRAINT FK_P10DeploymentPack FOREIGN KEY(InstitutionId,PackId) REFERENCES dbo.CRMAprendizajePaquete(InstitutionId,PackId);
ALTER TABLE dbo.CRMAprendizajeDespliegue ADD CONSTRAINT UQ_P10DeploymentPack UNIQUE(InstitutionId,PackId,DeploymentId);
CREATE TABLE dbo.CRMAprendizajePrediccion(InstitutionId uniqueidentifier NOT NULL,PredictionId uniqueidentifier NOT NULL,PackId uniqueidentifier NOT NULL,ArtifactId uniqueidentifier NOT NULL,GrantId uniqueidentifier NOT NULL,Mode varchar(8) NOT NULL,Document nvarchar(max) NOT NULL,ActorId uniqueidentifier NOT NULL,CreatedAt datetime2(7) NOT NULL CONSTRAINT DF_P10PredictionFecha DEFAULT SYSUTCDATETIME(),CONSTRAINT PK_P10Prediction PRIMARY KEY(InstitutionId,PredictionId),CONSTRAINT FK_P10PredictionActor FOREIGN KEY(InstitutionId,ActorId) REFERENCES dbo.CRMAccesoUsuario(InstitutionId,UserId),CONSTRAINT CK_P10Prediction CHECK(ISJSON(Document)=1 AND (Mode IN('shadow','active'))));
ALTER TABLE dbo.CRMAprendizajePrediccion ADD CONSTRAINT FK_P10PredictionPack FOREIGN KEY(InstitutionId,PackId) REFERENCES dbo.CRMAprendizajePaquete(InstitutionId,PackId);
ALTER TABLE dbo.CRMAprendizajePrediccion ADD CONSTRAINT UQ_P10PredictionPack UNIQUE(InstitutionId,PackId,PredictionId);
CREATE TABLE dbo.CRMAprendizajeEvento(InstitutionId uniqueidentifier NOT NULL,EventId uniqueidentifier NOT NULL,PackId uniqueidentifier NULL,Kind varchar(40) NOT NULL,Document nvarchar(max) NOT NULL,ActorId uniqueidentifier NOT NULL,CreatedAt datetime2(7) NOT NULL CONSTRAINT DF_P10EventFecha DEFAULT SYSUTCDATETIME(),CONSTRAINT PK_P10Event PRIMARY KEY(InstitutionId,EventId),CONSTRAINT FK_P10EventActor FOREIGN KEY(InstitutionId,ActorId) REFERENCES dbo.CRMAccesoUsuario(InstitutionId,UserId),CONSTRAINT CK_P10Event CHECK(ISJSON(Document)=1 AND (1=1)));
ALTER TABLE dbo.CRMAprendizajeEvento ADD CONSTRAINT FK_P10EventPack FOREIGN KEY(InstitutionId,PackId) REFERENCES dbo.CRMAprendizajePaquete(InstitutionId,PackId);
ALTER TABLE dbo.CRMAprendizajePaqueteVersion ADD CONSTRAINT UQ_P10PackVersion UNIQUE(InstitutionId,PackId,VersionNo);
ALTER TABLE dbo.CRMAprendizajeAutorizacion ADD CONSTRAINT UQ_P10GrantGroup UNIQUE(InstitutionId,PackId,GroupKey);
ALTER TABLE dbo.CRMAprendizajeDespliegue ADD CONSTRAINT UQ_P10DeploymentSelection UNIQUE(InstitutionId,PackId);
ALTER TABLE dbo.CRMAprendizajeMuestra ADD CONSTRAINT FK_P10SampleGrantId FOREIGN KEY(InstitutionId,PackId,GrantId) REFERENCES dbo.CRMAprendizajeAutorizacion(InstitutionId,PackId,GrantId);
ALTER TABLE dbo.CRMAprendizajeMuestra ADD CONSTRAINT FK_P10SampleVersionId FOREIGN KEY(InstitutionId,PackId,VersionId) REFERENCES dbo.CRMAprendizajePaqueteVersion(InstitutionId,PackId,VersionId);
ALTER TABLE dbo.CRMAprendizajeMuestra ADD CONSTRAINT FK_P10SampleSupersedes FOREIGN KEY(InstitutionId,PackId,Supersedes) REFERENCES dbo.CRMAprendizajeMuestra(InstitutionId,PackId,SampleId);
ALTER TABLE dbo.CRMAprendizajeConjunto ADD CONSTRAINT FK_P10DatasetVersionId FOREIGN KEY(InstitutionId,PackId,VersionId) REFERENCES dbo.CRMAprendizajePaqueteVersion(InstitutionId,PackId,VersionId);
ALTER TABLE dbo.CRMAprendizajeArtefacto ADD CONSTRAINT FK_P10ArtifactDatasetId FOREIGN KEY(InstitutionId,PackId,DatasetId) REFERENCES dbo.CRMAprendizajeConjunto(InstitutionId,PackId,DatasetId);
ALTER TABLE dbo.CRMAprendizajeDespliegue ADD CONSTRAINT FK_P10DeploymentActiveId FOREIGN KEY(InstitutionId,PackId,ActiveId) REFERENCES dbo.CRMAprendizajeArtefacto(InstitutionId,PackId,ArtifactId);
ALTER TABLE dbo.CRMAprendizajeDespliegue ADD CONSTRAINT FK_P10DeploymentShadowId FOREIGN KEY(InstitutionId,PackId,ShadowId) REFERENCES dbo.CRMAprendizajeArtefacto(InstitutionId,PackId,ArtifactId);
